package com.acxiom.crm.api; import com.acxiom.crm.opportunity.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/opportunities") public class OpportunityApiController {private final OpportunityRepository repo; public OpportunityApiController(OpportunityRepository r){repo=r;} @GetMapping public List<Opportunity> all(){return repo.findAll();} @GetMapping("/{id}") public Opportunity one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Opportunity create(@Valid @RequestBody Opportunity o){if(o.getCustomer()==null||o.getCustomer().getId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"customer.id is required");return repo.save(o);} }
